interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  life: number;
  maxLife: number;
  glow?: boolean;
}

interface FloatingText {
  x: number;
  y: number;
  text: string;
  color: string;
  fontSize: number;
  life: number;
  maxLife: number;
  vy: number;
  vx?: number;
  isDamage?: boolean;
  isCrit?: boolean;
  isRelic?: boolean;
}

interface ExpGem {
  x: number;
  y: number;
  value: number;
  color: string;
  radius: number;
  vx: number;
  vy: number;
}

interface TelegraphZone {
  x: number;
  y: number;
  radius: number;
  timer: number;
  maxTimer: number;
  color: string;
  onTrigger: () => void;
}

export interface SpatialZone {
  x: number;
  y: number;
  radius: number;
  duration: number;
  maxDuration: number;
  type:
    | 'traveler_chrono'
    | 'judge_collapse'
    | 'judge_barrier'
    | 'judge_domain'
    | 'elementalis_fissure'
    | 'elementalis_wind_vortex'
    | 'elementalis_tornado'
    | 'elementalis_fire_vortex'
    | 'elementalis_whirlpool'
    | 'arcana_gambit'
    | 'arcana_roulette'
    | 'arcana_afterimage'
    | 'axiom_cube'
    | 'kagero_domain'
    | 'architect_zone';
  color: string;
  pulseAngle: number;
  owner?: 'player' | 'corrupted_hero';
  tickTimer?: number;
  damage?: number;
  subTickTimer?: number;
  architectAddons?: CustomSkillAddon[];
  architectDamageMult?: number;
}

export interface Axiom3DProjectileSync {
  id: number;
  ndcX: number;
  ndcY: number;
  vx: number;
  vy: number;
  variant: 'prism' | 'blade' | 'hijacked' | 'sovereign_ray';
  color: string;
  isCrit: boolean;
}

export interface Axiom3DDominatedSync {
  id: number;
  ndcX: number;
  ndcY: number;
  radiusPx: number;
  hpRatio: number;
  timer: number;
}

export interface Axiom3DCubeZoneSync {
  ndcX: number;
  ndcY: number;
  radiusNormX: number;
  radiusNormY: number;
  progress: number;
  pulseAngle: number;
}

export interface Axiom3DFxEvent {
  id: number;
  type: 'slam' | 'betrayal' | 'deflect' | 'dominion' | 'hijack';
  ndcX: number;
  ndcY: number;
  radiusNorm: number;
  age: number;
  maxAge: number;
}

export interface Axiom3DSyncData {
  playerNdc: { x: number; y: number };
  facing: number;
  stacks: number;
  maxStacks: number;
  deflectReady: boolean;
  dominionTimer: number;
  atkFlash: number;
  skillPose: 'none' | 'slam' | 'betrayal' | 'guillotine' | 'cube' | 'dominion';
  skillPoseProgress: number;
  projectiles: Axiom3DProjectileSync[];
  dominatedEnemies: Axiom3DDominatedSync[];
  cubeZones: Axiom3DCubeZoneSync[];
  fxEvents: Axiom3DFxEvent[];
}

