  public handleResize() {
    const parent = this.canvas.parentElement;
    if (!parent) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = parent.getBoundingClientRect();
    this.width = rect.width;
    this.height = rect.height;

    this.canvas.width = Math.floor(rect.width * dpr);
    this.canvas.height = Math.floor(rect.height * dpr);
    this.canvas.style.width = `${rect.width}px`;
    this.canvas.style.height = `${rect.height}px`;

    this.ctx.resetTransform();
    this.ctx.scale(dpr, dpr);
  }

  private initEventListeners() {
    this.boundKeyDown = (e: KeyboardEvent) => {
      const activeTag = document.activeElement?.tagName;
      if (activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT') return;
      this.keysHeld[e.key.toLowerCase()] = true;
      if (e.key === ' ' || e.key === 'Spacebar') {
        this.triggerManualSkill(0);
      } else if (e.key === '1') {
        this.triggerManualSkill(0);
      } else if (e.key === '2') {
        this.triggerManualSkill(1);
      } else if (e.key === '3') {
        this.triggerManualSkill(2);
      } else if (e.key === '4') {
        this.triggerManualSkill(3);
      } else if (e.key === '5') {
        this.triggerManualSkill(4);
      }
    };

    this.boundKeyUp = (e: KeyboardEvent) => {
      this.keysHeld[e.key.toLowerCase()] = false;
    };

    this.boundBlur = () => {
      this.keysHeld = {};
    };

    this.boundPointerUp = () => {
      this.targetPointer.active = false;
    };

    window.addEventListener('keydown', this.boundKeyDown);
    window.addEventListener('keyup', this.boundKeyUp);
    window.addEventListener('blur', this.boundBlur);
    window.addEventListener('pointerup', this.boundPointerUp);

    this.canvas.addEventListener('pointerdown', (e) => {
      const rect = this.canvas.getBoundingClientRect();
      this.targetPointer.x = e.clientX - rect.left;
      this.targetPointer.y = e.clientY - rect.top;
      this.targetPointer.active = true;
    });

    this.canvas.addEventListener('pointermove', (e) => {
      if (this.targetPointer.active) {
        const rect = this.canvas.getBoundingClientRect();
        this.targetPointer.x = e.clientX - rect.left;
        this.targetPointer.y = e.clientY - rect.top;
      }
    });
  }

  public destroy() {
    this.stop();
    flushCodexProgress();
    if (this.boundKeyDown) window.removeEventListener('keydown', this.boundKeyDown);
    if (this.boundKeyUp) window.removeEventListener('keyup', this.boundKeyUp);
    if (this.boundBlur) window.removeEventListener('blur', this.boundBlur);
    if (this.boundPointerUp) window.removeEventListener('pointerup', this.boundPointerUp);
  }

  public setHero(heroKey: HeroKey, skills?: SkillDefinition[]) {
    this.heroKey = heroKey;
    this.heroConfig = HERO_DATABASE[heroKey];
    if (skills) {
      this.activeSkills = [...skills];
    } else if (heroKey === 'architect') {
      this.architectLoadout = cloneArchitectLoadout(DEFAULT_ARCHITECT_LOADOUT);
      this.activeSkills = buildArchitectSkillsFromLoadout(this.architectLoadout);
    } else {
      this.activeSkills = [...this.heroConfig.skills];
    }
    this.baseActiveSkills = [...this.activeSkills];
    this.resetRunState();
    this.onSkillsChange?.([...this.activeSkills]);
  }

  public setArchitectLoadout(loadout: ArchitectLoadout) {
    this.architectLoadout = cloneArchitectLoadout(loadout);
    if (this.heroKey === 'architect') {
      const rebuilt = buildArchitectSkillsFromLoadout(this.architectLoadout);
      const nextSkills = rebuilt.map((sk, idx) => {
        const prev = this.activeSkills[idx];
        return prev ? { ...sk, level: prev.level, maxLevel: prev.maxLevel } : sk;
      });
      this.activeSkills = nextSkills;
      this.baseActiveSkills = nextSkills.map(s => ({ ...s }));
      if (this.player) {
        this.player.architectCustomAttackName = this.architectLoadout.attackProgram.name;
        for (let i = 0; i < nextSkills.length; i++) {
          const isImmune = this.isCdReductionImmuneSkill(i);
          const minCd = nextSkills[i].id.startsWith('arc_custom_') ? 3.5 : 1.0;
          const newMax = isImmune ? nextSkills[i].cd : Math.max(minCd, nextSkills[i].cd * (1 - (this.player.cdr || 0)));
          this.player.skillMaxCDs[i] = newMax;
          this.player.skillCDs[i] = Math.min(this.player.skillCDs[i] || 0, newMax);
        }
      }
      this.onSkillsChange?.([...this.activeSkills]);
      this.recalculateStats();
      this.pushStatsUpdate();
    }
  }

  public setPracticeMode(enabled: boolean) {
    this.practiceMode = enabled;
  }

  public applyEasterEggChronicleBlessing() {
    if (this.easterEggBlessingUsed) return;
    this.easterEggBlessingUsed = true;
    this.bonusAtk += Math.round(this.heroConfig.atk * 0.18);
    this.bonusAtkSpeed += 0.18;
    this.bonusCritChance += 0.10;
    this.aegisShield = Math.min(this.getMaxAegisShieldCap(), this.aegisShield + 400);
    this.aegisShieldTimer = Math.max(this.aegisShieldTimer, 12.0);
    this.player.aegisShield = this.aegisShield;
    this.healPlayer(this.player.maxHp);
    this.recalculateStats();
    this.createShockwave(this.playerPos.x, this.playerPos.y, '#fde047', 220);
    this.createShockwave(this.playerPos.x, this.playerPos.y, '#22d3ee', 160);
    this.floatingTexts.push({
      x: this.playerPos.x,
      y: this.playerPos.y - 46,
      text: '✨ OMEGA CHRONICLE BLESSING AKTIF!',
      color: '#fde047',
      fontSize: 18,
      life: 2.2,
      maxLife: 2.2,
      vy: -24
    });
    this.pushStatsUpdate();
  }

  public start() {
    this.isPaused = false;
    this.isGameOver = false;
    this.lastTime = performance.now();
    recordCodexHeroRun(this.heroKey);
    if (this.practiceMode) {
      this.wave = this.practiceWaveLevel;
      this.spawnPracticeDummy('static', Math.min(this.width - 70, this.width * 0.65), this.height * 0.48);
      this.spawnPracticeDummy('static', Math.min(this.width - 70, this.width * 0.65), this.height * 0.30);
    } else {
      this.spawnWave();
    }
    if (!this.animationId) {
      this.animationId = requestAnimationFrame(this.gameLoop.bind(this));
    }
  }

  public stop() {
    if (this.animationId) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
  }

