    if (this.frostPrismCd > 0) {
      this.frostPrismCd = Math.max(0, this.frostPrismCd - dt);
    }
    if (this.synergyBastionShieldCd > 0) {
      this.synergyBastionShieldCd = Math.max(0, this.synergyBastionShieldCd - dt);
    }
