        const demonX = Math.max(40, Math.min(this.width - 40, this.playerPos.x + 55 + (Math.random() - 0.5) * 35));
        const demonY = Math.max(40, Math.min(this.height - 40, this.playerPos.y + (Math.random() - 0.5) * 70));
        this.spawnDualSummon('angel', angelX, angelY);
