            this.createShockwave(z.x, z.y, '#0ea5e9', z.radius * 0.85);
            let hitAny = false;
            for (const e of this.enemies) {
              if (e.hp > 0 && Math.hypot(e.x - z.x, e.y - z.y) <= z.radius) {
                hitAny = true;
                const wpCrit = hasTsunami ? true : (Math.random() < this.player.critChance);
                const wpDmg = this.player.atk * 0.90 * (wpCrit ? this.player.critDmg : 1.0);
                e.takeDamage(wpDmg, wpCrit, 'player', this, 'magical');
                const trueHpDmg = Math.min(e.isBoss ? 220 : 280, Math.round(e.maxHp * (hasTsunami ? 0.03 : 0.02)));
                e.takeDamage(trueHpDmg, false, 'true_damage', this);
                this.applyElementalisFlaming(e);
              }
            }
            if (hitAny) {
              this.healPlayer(this.player.maxHp * 0.015);
              this.restorePoseidonArmor(35, 1.5);
            }
