        const yankFromX = furthestEnemy.x;
        const yankFromY = furthestEnemy.y;
        furthestEnemy.x = Math.max(35, Math.min(this.width - 35, this.playerPos.x + Math.cos(angle) * 34));
        furthestEnemy.y = Math.max(35, Math.min(this.height - 35, this.playerPos.y + Math.sin(angle) * 34));
        this.createLaserBeam(yankFromX, yankFromY, furthestEnemy.x, furthestEnemy.y, '#bae6fd', 8);
        this.createShockwave(yankFromX, yankFromY, '#7dd3fc', 65);
