      const isEquinox = this.luminaFusionTimer > 0;
      const isLightAspect = this.luminaForm === 'light';
      const aspectSurge = this.luminaAspectSurgeTimer > 0 ? 0.15 : 0;
      const lightAtk = isEquinox ? 0.35 : (isLightAspect ? 0.18 : 0);
      const lightAspd = (isEquinox ? 0.32 : (isLightAspect ? 0.20 : 0)) + (this.luminaLightAspdTimer > 0 ? 0.18 : 0);
      this.player.atk = (cfg.atk + extraAtk) * (1 + charges * 0.015 + lightAtk + aspectSurge);
      this.player.atkSpeed = cfg.atkSpeed + extraASPD + warpASPD + charges * 0.012 + lightAspd + aspectSurge;
      this.player.speed = cfg.speed + this.bonusSpeed + chronoSpeedBonus + warpSpeed + (isEquinox ? 50 : 0);
