      const domAtkBonus = isDominion ? (godManipulation ? 0.65 : 0.45) : 0;
      const domAspdBonus = isDominion ? 0.35 : 0;

      this.player.atk = (cfg.atk + extraAtk) * (1 + stacks * 0.02 + cubeAtkBonus + domAtkBonus);
      this.player.atkSpeed = cfg.atkSpeed + extraASPD + warpASPD + cubeAspdBonus + domAspdBonus;
